# R/core/08_code_parsers.R
# Reads VOF code back into components/metadata:
#   * parse_vof_code(): code generated by this app ("Restore Project").
#   * parse_legacy_r_code(): hand-written AWB VOF code ("Import Legacy R").
# Both work on R's own parse tree (never evaluated), so quotes, commas or
# parentheses inside values and multi-line statements are handled correctly.

# ------------------------------------------------------------------------------
# Parse-tree helpers
# ------------------------------------------------------------------------------
call_name <- function(e) if (is.call(e) && is.name(e[[1]])) as.character(e[[1]]) else ""

# TRUE when element i of a call is an empty argument (e.g. the row index of
# Data[, "x"]). Must be checked before binding the element to a variable.
is_empty_arg <- function(lst, i) identical(lst[[i]], quote(expr = ))

# Non-empty arguments of a call.
call_args <- function(e) {
  lst <- as.list(e)[-1]
  lst[!map_lgl(seq_along(lst), ~ is_empty_arg(lst, .x))]
}

is_data_ref <- function(e, data_name = "Data") is.name(e) && identical(as.character(e), data_name)

# Parses code into a list of top-level expressions. If the whole text does not
# parse, falls back to statement-per-line and reports the lines it skipped.
safe_parse_statements <- function(text) {
  exprs <- tryCatch(as.list(parse(text = text, keep.source = FALSE)), error = function(e) NULL)
  if (!is.null(exprs)) return(list(exprs = exprs, skipped = 0L))
  exprs <- list(); skipped <- 0L
  for (line in str_split(text, fixed("\n"))[[1]]) {
    if (str_trim(line) == "") next
    p <- tryCatch(as.list(parse(text = line, keep.source = FALSE)), error = function(e) NULL)
    if (is.null(p)) skipped <- skipped + 1L else exprs <- c(exprs, p)
  }
  list(exprs = exprs, skipped = skipped)
}

# All character constants inside an expression.
string_constants <- function(e) {
  if (is.character(e)) return(e)
  if (is.call(e)) return(as.character(unlist(map(call_args(e), string_constants))))
  character(0)
}

# Column names referenced as Data$x, Data[["x"]], Data["x"], Data[i, "x"] or
# Data[i, c("x", "y")] anywhere inside an expression.
column_refs <- function(e) {
  if (!is.call(e)) return(character(0))
  fn <- call_name(e)
  args <- as.list(e)
  own <- character(0)
  if (fn == "$" && is_data_ref(args[[2]])) own <- as.character(args[[3]])
  if (fn == "[[" && is_data_ref(args[[2]]) && length(args) >= 3) own <- string_constants(args[[3]])
  if (fn == "[" && is_data_ref(args[[2]])) {
    j_idx <- if (length(args) >= 4) 4 else if (length(args) == 3) 3 else 0
    if (j_idx > 0 && !is_empty_arg(args, j_idx)) own <- string_constants(args[[j_idx]])
  }
  c(own, as.character(unlist(map(call_args(e), column_refs))))
}

# Target column of an assignment's left-hand side plus its row filter, if any.
lhs_target <- function(lhs) {
  fn <- call_name(lhs)
  args <- as.list(lhs)
  if (fn == "$" && is_data_ref(args[[2]])) return(list(name = as.character(args[[3]]), filter = NULL))
  if (fn == "[[" && is_data_ref(args[[2]])) {
    s <- string_constants(args[[3]]); if (length(s) == 1) return(list(name = s, filter = NULL))
  }
  if (fn == "[" && is_data_ref(args[[2]])) {
    if (length(args) == 4) {
      s <- string_constants(args[[4]])
      if (length(s) == 1) return(list(name = s, filter = if (is_empty_arg(args, 3)) NULL else args[[3]]))
    } else if (length(args) == 3) {
      s <- string_constants(args[[3]]); if (length(s) == 1) return(list(name = s, filter = NULL))
    }
  }
  NULL
}

refers_to_col <- function(e, col) {
  if (is.name(e)) return(identical(as.character(e), col))
  fn <- call_name(e)
  if (fn == "$" && is_data_ref(e[[2]])) return(identical(as.character(e[[3]]), col))
  if (fn == "[[" && is_data_ref(e[[2]])) return(identical(string_constants(e[[3]]), col))
  if (fn %in% c("tolower", "toupper", "trimws", "as.character", "as.Date")) return(refers_to_col(e[[2]], col))
  FALSE
}

date_constant <- function(e) {
  s <- string_constants(e)
  if (length(s) != 1) return(NA_character_)
  format_date_iso(s)
}

# Period and cross-sectional filters found anywhere in an expression.
# CS conditions: %in% / == (Exact), startsWith, endsWith and
# grepl(fixed = TRUE) (Contains); a `!` around them makes the filter "exclude".
# Conditions on the same dimension are combined as levels of one filter.
extract_filters <- function(e) {
  res <- list(start = NA_character_, end = NA_character_, cs = list(), negated = FALSE)
  add_level <- function(dim, match, values, negated) {
    f <- res$cs[[dim]] %||% list(mode = if (negated) "exclude" else "include", levels = list())
    # The same condition usually appears twice (row index of the LHS and RHS).
    if (some(f$levels, ~ .x$match == match && setequal(.x$values, values))) return(invisible())
    same <- detect_index(f$levels, ~ .x$match == match && match == "Exact")
    if (same > 0) f$levels[[same]]$values <- unique(c(f$levels[[same]]$values, values))  # legacy: several %in% on one dim
    else f$levels <- c(f$levels, list(list(match = match, values = values)))
    if (negated) f$mode <- "exclude"
    res$cs[[dim]] <<- f
  }
  cs_dim_of <- function(x) detect(MFF_DIMS, ~ refers_to_col(x, .x))
  walk_expr <- function(x, negated = FALSE) {
    if (!is.call(x)) return(invisible())
    fn <- call_name(x)
    if (fn == "(") { walk_expr(x[[2]], negated); return(invisible()) }
    if (fn == "!") { walk_expr(x[[2]], !negated); return(invisible()) }
    if (fn %in% c(">=", ">", "<=", "<") && length(x) == 3) {
      lhs_p <- refers_to_col(x[[2]], PERIOD_COL); rhs_p <- refers_to_col(x[[3]], PERIOD_COL)
      if (lhs_p || rhs_p) {
        if (negated) { res$negated <<- TRUE; return(invisible()) }
        d <- date_constant(if (lhs_p) x[[3]] else x[[2]])
        lower <- (fn %in% c(">=", ">")) == lhs_p
        if (!is.na(d) && d != "") { if (lower) res$start <<- d else res$end <<- d }
        return(invisible())
      }
    }
    if (fn %in% c("%in%", "==") && length(x) == 3) {
      side <- 0; dim <- cs_dim_of(x[[2]])
      if (!is.null(dim)) side <- 3 else { dim <- cs_dim_of(x[[3]]); if (!is.null(dim)) side <- 2 }
      if (side > 0) {
        vals <- string_constants(x[[side]])
        if (length(vals) > 0) add_level(dim, "Exact", vals, negated)
        return(invisible())
      }
    }
    if (fn %in% c("startsWith", "endsWith") && length(x) >= 3) {
      dim <- cs_dim_of(x[[2]])
      if (!is.null(dim)) {
        add_level(dim, if (fn == "startsWith") "StartsWith" else "EndsWith", string_constants(x[[3]]), negated)
        return(invisible())
      }
    }
    if (fn == "grepl" && length(x) >= 3) {
      dim <- cs_dim_of(x[[3]])
      if (!is.null(dim)) {
        add_level(dim, "Contains", string_constants(x[[2]]), negated)
        return(invisible())
      }
    }
    # An OR of conditions on the same dimension and match type is one level.
    if (fn == "|") {
      leaves <- map(or_leaves(x), extract_filters)
      single <- every(leaves, ~ length(.x$cs) == 1 && length(.x$cs[[1]]$levels) == 1 &&
                        .x$cs[[1]]$mode == "include" && is.na(.x$start) && is.na(.x$end))
      if (single) {
        dims <- unique(map_chr(leaves, ~ names(.x$cs)))
        matches <- unique(map_chr(leaves, ~ .x$cs[[1]]$levels[[1]]$match))
        if (length(dims) == 1 && length(matches) == 1) {
          add_level(dims, matches, unique(unlist(map(leaves, ~ .x$cs[[1]]$levels[[1]]$values))), negated)
          return(invisible())
        }
      }
    }
    for (a in call_args(x)) walk_expr(a, negated)
    invisible()
  }
  walk_expr(e)
  res
}

# Operands of a chain "a | b | c" (parentheses removed).
or_leaves <- function(x) {
  if (call_name(x) == "(") return(or_leaves(x[[2]]))
  if (call_name(x) == "|") return(c(or_leaves(x[[2]]), or_leaves(x[[3]])))
  list(x)
}

is_assignment <- function(e) call_name(e) %in% c("<-", "=") && length(e) == 3

# ------------------------------------------------------------------------------
# Restore: code generated by this app
# ------------------------------------------------------------------------------
parse_metadata_comment <- function(comment) {
  txt <- str_remove(comment, "^#\\s*")
  get <- function(labels) {
    for (label in labels) {
      v <- str_match(txt, str_c(label, ":\\s*([^;]*)"))[1, 2]
      if (!is.na(v)) return(str_trim(v))
    }
    ""
  }
  list(variable_name = get(c("VariableName", "Media Channel")),
       complement = get(c("Complement", "Sub Channel")),
       effect = get("Effect"))
}

# Splits a feed line into its code expression and trailing comment.
split_code_comment <- function(line) {
  pd <- tryCatch({
    p <- parse(text = line, keep.source = TRUE)
    list(expr = p[[1]], data = utils::getParseData(p))
  }, error = function(e) NULL)
  if (is.null(pd) || length(pd$expr) == 0) return(NULL)
  comments <- pd$data$text[pd$data$token == "COMMENT"]
  list(expr = pd$expr, comment = if (length(comments) > 0) comments[length(comments)] else "")
}

# Returns a named list (VOF name -> list(name, components, backcasting)) in the
# order the VOFs appear in the code. Backcasting is read per section (VOF).
parse_vof_code <- function(code_text) {
  lines <- str_split(code_text, fixed("\n"))[[1]] %>% str_trim()
  vofs <- list()
  section_vofs <- character(0)
  bc <- list(start = NA_character_, end = NA_character_)

  close_section <- function() {
    if (length(section_vofs) > 0 && !is.na(bc$start) && !is.na(bc$end)) {
      for (v in section_vofs) vofs[[v]]$backcasting <<- list(enabled = TRUE, start = as_date(bc$start), end = as_date(bc$end))
    }
    section_vofs <<- character(0)
    bc <<- list(start = NA_character_, end = NA_character_)
  }

  for (tl in lines) {
    if (str_detect(tl, "^####")) { close_section(); next }
    m <- str_match(tl, "^(lower_bound|upper_bound)\\s*<-\\s*as\\.Date\\((['\"])(.*)\\2\\)")
    if (!is.na(m[1, 1])) {
      if (m[1, 2] == "lower_bound") bc$start <- format_date_iso(m[1, 4]) else bc$end <- format_date_iso(m[1, 4])
      next
    }
    if (!str_detect(tl, fixed("rowSums"))) next
    sc <- split_code_comment(tl)
    if (is.null(sc) || !is_assignment(sc$expr)) next
    target <- lhs_target(sc$expr[[2]])
    if (is.null(target)) next
    roots <- setdiff(unique(column_refs(sc$expr[[3]])), c(target$name, PERIOD_COL, MFF_DIMS))
    if (length(roots) == 0) next
    filters <- extract_filters(sc$expr)
    meta <- parse_metadata_comment(sc$comment)
    if (is.null(vofs[[target$name]]))
      vofs[[target$name]] <- list(name = target$name, components = list(), backcasting = list(enabled = FALSE))
    new_comps <- map(roots, ~ new_component(
      analytical_var = .x, variable_name = strip_backcasted_label(meta$variable_name),
      complement = meta$complement, effect = meta$effect,
      start_period = filters$start, end_period = filters$end, cs = filters$cs))
    vofs[[target$name]]$components <- c(vofs[[target$name]]$components, new_comps)
    section_vofs <- union(section_vofs, target$name)
  }
  close_section()
  vofs
}

# Metric of a VOF read back from its name ("...---Imps") or, for older names
# without suffix, from its roots.
metric_from_vof <- function(vof_name, components, long_dims) {
  suffix <- str_match(vof_name, str_c(METRIC_SEP_REGEX, "([^-]+)$"))[1, 2]
  row <- METRICS %>% filter(Suffix == suffix %|NA|% "")
  if (nrow(row) > 0) return(list(type = row$Type[1], metric = if (row$Type[1] == "Spend") "Spend" else row$Metric[1]))
  m <- detect_metric(components[[1]]$analytical_var, long_dims)
  if (is.null(m)) return(list(type = "Activity", metric = ""))
  list(type = m$Type, metric = if (m$Type == "Spend") "Spend" else m$Metric)
}

# Metadata rows for every VOF found by parse_vof_code(). The name flags are
# read back from the VOF name.
parsed_vofs_to_metadata <- function(vofs, cs_dims) {
  long_dims <- longitudinal_dims(cs_dims)
  map(vofs, function(v) {
    m <- metric_from_vof(v$name, v$components, long_dims)
    labels <- name_cs_labels(v$name, cs_dims)
    build_media_metadata(v$name, v$components, cs_dims, m$metric, v$backcasting, labels)
  }) %>% list_rbind()
}

# ------------------------------------------------------------------------------
# Legacy: hand-written VOF code
# ------------------------------------------------------------------------------
# Deduces the media channel of each root from the legacy VOF name: the part
# before the first "--" is split into tokens ("A and B" or "A-B") and each root
# is assigned the longest token it contains.
assign_media_channels <- function(vof_name, roots) {
  base <- str_split(vof_name, fixed("--"))[[1]][1]
  tokens <- (if (str_detect(base, regex("\\s+and\\s+", ignore_case = TRUE)))
               str_split(base, regex("\\s+and\\s+", ignore_case = TRUE))[[1]]
             else str_split(base, "\\s*-\\s*")[[1]]) %>%
    str_trim() %>% keep(nzchar)
  out <- map_chr(roots, function(root) {
    hits <- keep(tokens, ~ str_detect(str_to_lower(root), fixed(str_to_lower(.x))))
    if (length(hits) > 0) hits[which.max(nchar(hits))] else NA_character_
  })
  unused <- setdiff(tokens, out)
  if (length(unused) == 1) out[is.na(out)] <- unused
  replace_na(out, str_trim(base))
}

legacy_effect <- function(vof_name) {
  tag <- str_trim(str_split(vof_name, fixed("--"))[[1]][2])
  case_when(is.na(tag) ~ "",
            str_detect(tag, regex("^Direct", ignore_case = TRUE)) ~ "Direct",
            str_detect(tag, regex("^Halo", ignore_case = TRUE)) ~ "Halo",
            TRUE ~ "")
}

parse_legacy_r_code <- function(code_text, mff_vars, cs_dims) {
  parsed <- safe_parse_statements(code_text)
  definitions <- list()
  negated_found <- FALSE

  collect <- function(e) {
    if (call_name(e) == "{") { for (x in as.list(e)[-1]) collect(x); return(invisible()) }
    if (!is_assignment(e)) return(invisible())
    target <- lhs_target(e[[2]])
    if (is.null(target)) return(invisible())
    rhs <- e[[3]]
    if (is.numeric(rhs) && length(rhs) == 1) return(invisible())  # initialisation (<- 0)
    comps <- setdiff(unique(column_refs(rhs)), c(target$name, PERIOD_COL, MFF_DIMS))
    if (length(comps) == 0) return(invisible())
    f <- extract_filters(e)
    if (isTRUE(f$negated)) negated_found <<- TRUE
    block <- list(vars = comps, filters = list(start = f$start, end = f$end, cs = f$cs))
    definitions[[target$name]] <<- c(definitions[[target$name]], list(block))
    invisible()
  }
  for (e in parsed$exprs) collect(e)

  merge_filters <- function(parent, child) {
    start <- parent$start
    if (!is.na(child$start) && (is.na(start) || child$start > start)) start <- child$start
    end <- parent$end
    if (!is.na(child$end) && (is.na(end) || child$end < end)) end <- child$end
    cs <- parent$cs
    for (k in names(child$cs)) cs[[k]] <- child$cs[[k]]
    list(start = start, end = end, cs = cs)
  }
  # Walks nested VOFs down to MFF variables, accumulating filters.
  resolve <- function(var, acc, path = character(0)) {
    if (var %in% mff_vars) return(list(list(root = var, filters = acc)))
    if (var %in% path || is.null(definitions[[var]])) return(list())
    out <- list()
    for (block in definitions[[var]]) {
      merged <- merge_filters(acc, block$filters)
      for (comp in block$vars) out <- c(out, resolve(comp, merged, c(path, var)))
    }
    out
  }

  rows <- list()
  for (vof_name in names(definitions)) {
    leaves <- resolve(vof_name, list(start = NA_character_, end = NA_character_, cs = list()))
    if (length(leaves) == 0) next
    roots <- map_chr(leaves, "root")
    channels <- assign_media_channels(vof_name, roots)
    effect <- legacy_effect(vof_name)
    comps <- pmap(list(leaves, roots, channels), function(leaf, root, channel) {
      fl <- leaf$filters
      new_component(analytical_var = root, variable_name = channel, effect = effect,
                    start_period = fl$start, end_period = fl$end, cs = fl$cs)
    })
    m <- metric_from_vof(vof_name, comps, longitudinal_dims(cs_dims))
    rows[[length(rows) + 1]] <- build_media_metadata(vof_name, comps, cs_dims, m$metric, list(enabled = FALSE))
  }
  list(metadata = normalize_metadata(list_rbind(rows), cs_dims),
       skipped_lines = parsed$skipped, negated_filters = negated_found)
}
